/// One server the contract declares, with its URL template variables.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct ServerTemplate {
    /// The URL, possibly containing `{variable}` placeholders.
    pub url: &'static str,
    /// The server's description from the contract.
    pub description: &'static str,
    /// The variables the template accepts.
    pub variables: &'static [ServerVariable],
}

/// One `{variable}` of a [`ServerTemplate`].
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct ServerVariable {
    /// The placeholder name.
    pub name: &'static str,
    /// The value used when the caller supplies none.
    pub default: Option<&'static str>,
    /// The values the contract allows; empty means unconstrained.
    pub allowed: &'static [&'static str],
}

/// Resolve the URL of `SERVERS[index]`, substituting `overrides` and then each variable's default.
///
/// Fails when the index is out of range, a variable has neither an override nor a
/// default, or an override is outside the variable's allowed values.
pub fn server_url(index: usize, overrides: &[(&str, &str)]) -> Result<String, ApiError> {
    const OPERATION: &str = "server_url";
    let server = SERVERS
        .get(index)
        .ok_or_else(|| ApiError::configuration(format!("no server at index {index}"), OPERATION))?;
    let mut url = server.url.to_owned();
    for variable in server.variables {
        let value = match overrides.iter().find(|(name, _)| *name == variable.name) {
            Some((_, value)) => {
                if !variable.allowed.is_empty() && !variable.allowed.contains(value) {
                    return Err(ApiError::configuration(
                        format!("server variable {} does not allow {value:?}", variable.name),
                        OPERATION,
                    ));
                }
                (*value).to_owned()
            }
            None => variable
                .default
                .ok_or_else(|| {
                    ApiError::configuration(
                        format!("server variable {} has no default", variable.name),
                        OPERATION,
                    )
                })?
                .to_owned(),
        };
        url = url.replace(&format!("{{{}}}", variable.name), &value);
    }
    for (name, _) in overrides {
        if !server
            .variables
            .iter()
            .any(|variable| variable.name == *name)
        {
            return Err(ApiError::configuration(
                format!("unknown server variable {name}"),
                OPERATION,
            ));
        }
    }
    Ok(url)
}

fn insert_header(
    headers: &mut HeaderMap,
    name: &str,
    value: &str,
    operation: &str,
) -> Result<(), ApiError> {
    let name = HeaderName::from_bytes(name.as_bytes()).map_err(|error| {
        ApiError::configuration(format!("invalid header name: {error}"), operation)
    })?;
    let value = HeaderValue::from_bytes(value.as_bytes()).map_err(|error| {
        ApiError::configuration(format!("invalid header value: {error}"), operation)
    })?;
    headers.insert(name, value);
    Ok(())
}

fn decoded_body(bytes: &[u8]) -> Value {
    serde_json::from_slice(bytes)
        .unwrap_or_else(|_| Value::String(String::from_utf8_lossy(bytes).into_owned()))
}

fn request_id(headers: &HeaderMap) -> Option<String> {
    ["x-request-id", "request-id", "x-correlation-id"]
        .iter()
        .find_map(|name| {
            headers
                .get(*name)
                .and_then(|value| value.to_str().ok())
                .map(str::to_owned)
        })
}

// 408 Request Timeout, 409 Conflict, 429 Too Many Requests and every 5xx are
// transient; 425 Too Early never is. Whether a retry happens is still gated on
// the operation being idempotent.
fn retryable_status(status: StatusCode) -> bool {
    matches!(status.as_u16(), 408 | 409 | 429) || status.is_server_error()
}

// `x-should-retry: true` or `false` is the server's own verdict and overrides
// the status policy.
fn should_retry(status: StatusCode, headers: &HeaderMap) -> bool {
    match headers
        .get("x-should-retry")
        .and_then(|value| value.to_str().ok())
        .map(str::trim)
    {
        Some("true") => true,
        Some("false") => false,
        _ => retryable_status(status),
    }
}

fn jitter() -> f64 {
    use std::hash::{BuildHasher, Hasher};
    let sample = std::collections::hash_map::RandomState::new()
        .build_hasher()
        .finish();
    (sample >> 11) as f64 / (1_u64 << 53) as f64
}

fn days_from_civil(year: i64, month: u64, day: u64) -> i64 {
    let year = if month <= 2 { year - 1 } else { year };
    let era = if year >= 0 { year } else { year - 399 } / 400;
    let year_of_era = (year - era * 400) as u64;
    let shifted_month = (month + 9) % 12;
    let day_of_year = (153 * shifted_month + 2) / 5 + day - 1;
    let day_of_era = year_of_era * 365 + year_of_era / 4 - year_of_era / 100 + day_of_year;
    era * 146_097 + day_of_era as i64 - 719_468
}

/// Parse the three HTTP-date forms RFC 9110 admits (IMF-fixdate, RFC 850, asctime).
fn parse_http_date(value: &str) -> Option<SystemTime> {
    const MONTHS: [&str; 12] = [
        "jan", "feb", "mar", "apr", "may", "jun", "jul", "aug", "sep", "oct", "nov", "dec",
    ];
    let tokens: Vec<&str> = value
        .split([' ', ','])
        .filter(|token| !token.is_empty())
        .collect();
    let (day, month, year, clock) = match tokens.as_slice() {
        [_, day, month, year, clock, zone] if zone.eq_ignore_ascii_case("gmt") => {
            (*day, *month, *year, *clock)
        }
        [_, date, clock, zone] if zone.eq_ignore_ascii_case("gmt") => {
            let mut parts = date.split('-');
            (parts.next()?, parts.next()?, parts.next()?, *clock)
        }
        [_, month, day, clock, year] => (*day, *month, *year, *clock),
        _ => return None,
    };
    let day: u64 = day.parse().ok()?;
    let month = MONTHS
        .iter()
        .position(|name| name.eq_ignore_ascii_case(month))? as u64
        + 1;
    let mut year: i64 = year.parse().ok()?;
    if year < 100 {
        year += if year < 70 { 2000 } else { 1900 };
    }
    let mut clock = clock.split(':');
    let hour: u64 = clock.next()?.parse().ok()?;
    let minute: u64 = clock.next()?.parse().ok()?;
    let second: u64 = clock.next()?.parse().ok()?;
    if !(1..=31).contains(&day) || hour > 23 || minute > 59 || second > 60 {
        return None;
    }
    let seconds =
        days_from_civil(year, month, day) * 86_400 + (hour * 3_600 + minute * 60 + second) as i64;
    u64::try_from(seconds)
        .ok()
        .map(|seconds| UNIX_EPOCH + Duration::from_secs(seconds))
}

/// A non-negative decimal count (`2` or `1.5`), the one number form a retry header takes.
fn retry_number(text: &str) -> Option<f64> {
    let (whole, fraction) = text.split_once('.').unwrap_or((text, "0"));
    let digits = |part: &str| !part.is_empty() && part.bytes().all(|byte| byte.is_ascii_digit());
    if digits(whole) && digits(fraction) {
        text.parse().ok()
    } else {
        None
    }
}

/// Seconds as a wait; one too long for `Duration` is still longer than any `max_retry_delay`.
fn retry_seconds(seconds: f64) -> Duration {
    Duration::try_from_secs_f64(seconds).unwrap_or(Duration::MAX)
}

/// The wait the server asked for: `retry-after-ms`, then `Retry-After` in seconds or as an
/// HTTP-date, then the IETF RateLimit reset (`t=` of `RateLimit`, or `RateLimit-Reset`).
fn server_retry_delay(headers: &HeaderMap) -> Option<Duration> {
    let header = |name: &str| {
        headers
            .get(name)
            .and_then(|value| value.to_str().ok())
            .map(str::trim)
    };
    if let Some(milliseconds) = header("retry-after-ms").and_then(retry_number) {
        return Some(retry_seconds(milliseconds / 1000.0));
    }
    if let Some(value) = header(RETRY_AFTER.as_str()) {
        if let Some(seconds) = retry_number(value) {
            return Some(retry_seconds(seconds));
        }
        if let Some(instant) = parse_http_date(value) {
            return Some(
                instant
                    .duration_since(SystemTime::now())
                    .unwrap_or(Duration::ZERO),
            );
        }
    }
    let digits =
        |value: &&str| !value.is_empty() && value.bytes().all(|byte| byte.is_ascii_digit());
    let reset = header("ratelimit")
        .and_then(|value| {
            value
                .split([';', ',', ' ', '\t'])
                .filter_map(|part| part.strip_prefix("t="))
                .find(digits)
        })
        .or_else(|| header("ratelimit-reset").filter(digits))?;
    reset.parse::<f64>().ok().map(retry_seconds)
}

type ErrorBodyDecoder = fn(u16, &[u8]) -> Option<ErrorBody>;

async fn bounded_body(
    mut response: reqwest::Response,
    operation: &str,
    attempts: u32,
    limit: u64,
) -> Result<(StatusCode, HeaderMap, Vec<u8>), ApiError> {
    let status = response.status();
    let headers = response.headers().clone();
    if response
        .content_length()
        .is_some_and(|length| length > limit)
    {
        return Err(ApiError::ResponseTooLarge {
            operation: operation.to_owned(),
            limit,
            attempts,
        });
    }
    let mut body = Vec::new();
    while let Some(chunk) = response
        .chunk()
        .await
        .map_err(|error| ApiError::transport(error, operation, attempts))?
    {
        if (body.len() as u64).saturating_add(chunk.len() as u64) > limit {
            return Err(ApiError::ResponseTooLarge {
                operation: operation.to_owned(),
                limit,
                attempts,
            });
        }
        body.extend_from_slice(&chunk);
    }
    Ok((status, headers, body))
}

async fn http_error(
    response: reqwest::Response,
    operation: &str,
    attempts: u32,
    typed: ErrorBodyDecoder,
    limit: u64,
) -> ApiError {
    let (status, headers, bytes) = match bounded_body(response, operation, attempts, limit).await {
        Ok(parts) => parts,
        Err(error) => return error,
    };
    let retryable = should_retry(status, &headers);
    ApiError::Status {
        status,
        typed: typed(status.as_u16(), &bytes).map(Box::new),
        request_id: request_id(&headers),
        headers: Box::new(headers),
        body: Box::new(decoded_body(&bytes)),
        operation: operation.to_owned(),
        attempts,
        retryable,
    }
}

/// The error schemas this contract declares for non-success responses.
///
/// This contract declares none, so `ApiError::typed` is always `None`.
#[derive(Debug, Clone)]
#[non_exhaustive]
pub enum ErrorBody {}

/// The servers the contract declares, in document order.
pub const SERVERS: &[ServerTemplate] = &[ServerTemplate {
    url: "https://api.codejackrabbit.com",
    description: "CodeJackRabbit Cloud & Self-Hosted API",
    variables: &[],
}];

impl ApiError {
    fn authentication(operation: &str, scheme: &str) -> Self {
        Self::Authentication {
            scheme: scheme.to_owned(),
            operation: operation.to_owned(),
        }
    }
}

struct SecurityParameters;

/// The lower-cased header or query names that carry a credential: `Authorization`,
/// `Proxy-Authorization` and `Cookie`, and every API-key security scheme's name there.
fn credential_names(location: &str) -> &'static [&'static str] {
    match location {
        "header" => &[
            "authorization",
            "proxy-authorization",
            "cookie",
            "x-codejackrabbit-api-key",
        ],
        _ => &[],
    }
}

fn no_error_body(_status: u16, _bytes: &[u8]) -> Option<ErrorBody> {
    None
}

/// One call's walk through its attempts, endpoints and retry waits.
///
/// A transient failure is retried only when the operation is idempotent or the request
/// carries an `Idempotency-Key`. The wait is
/// the server's own when it declares one that fits `max_retry_delay`, else jittered
/// exponential backoff, and `retry_budget` caps the whole call. Only an idempotent
/// operation moves to the next fallback base URL, after a transport failure or a 5xx.
struct RetryState<'a> {
    policy: &'a RetryPolicy,
    operation: &'static str,
    endpoints: Vec<&'a str>,
    endpoint: usize,
    url: String,
    attempt: u32,
    max_retries: u32,
    allowed: bool,
    started: std::time::Instant,
    // What the lifecycle hooks and the span observe (tk omniwrap-55457rp5).
    secrets: Vec<String>,
    method: String,
    observed_url: String,
    observed_headers: Vec<(String, String)>,
    status: Option<u16>,
    span: Option<Box<dyn TraceSpan>>,
}

impl<'a> RetryState<'a> {
    fn new(
        client: &'a Client,
        operation: &'static str,
        idempotent: bool,
        max_retries: Option<u32>,
    ) -> Self {
        let mut endpoints = vec![client.base_url.as_str()];
        // Fallback endpoints serve idempotent operations only.
        if idempotent {
            endpoints.extend(client.retry.fallback_base_urls.iter().map(String::as_str));
        }
        Self {
            policy: &client.retry,
            operation,
            endpoints,
            endpoint: 0,
            url: String::new(),
            attempt: 0,
            max_retries: max_retries.unwrap_or(client.max_retries),
            allowed: idempotent,
            started: std::time::Instant::now(),
            secrets: secret_values(&client.auth),
            method: String::new(),
            observed_url: String::new(),
            observed_headers: Vec::new(),
            status: None,
            span: None,
        }
    }

    /// Report the attempt about to be sent to `before_request`; the first one also opens the
    /// call's span. The URL and headers are redacted copies.
    fn before_request(
        &mut self,
        method: Method,
        url: &str,
        headers: &HeaderMap,
        query: &[(String, String)],
    ) {
        self.method = method.as_str().to_owned();
        self.status = None;
        self.observed_url = redacted_url(url, query, &self.secrets);
        self.observed_headers = redacted_headers(headers, &self.secrets);
        if self.span.is_none() {
            if let Some(tracer) = &self.policy.tracer {
                let method = SpanValue::Text(self.method.clone());
                self.span =
                    Some(tracer.start_span(self.operation, &[("http.request.method", method)]));
            }
        }
        if let Some(hook) = &self.policy.hooks.before_request {
            hook(&self.context(None, None));
        }
    }

    fn context(&self, error: Option<String>, retry_delay: Option<Duration>) -> HookContext {
        HookContext {
            operation_id: self.operation.to_owned(),
            method: self.method.clone(),
            url: self.observed_url.clone(),
            headers: self.observed_headers.clone(),
            attempt: self.attempt,
            elapsed: self.started.elapsed(),
            status: self.status,
            error,
            retry_delay,
        }
    }

    /// A failed attempt ends with `on_retry` when a wait follows, else with `on_error`.
    fn settle_failure(&self, error: Option<String>, wait: Option<Duration>) {
        let hook = if wait.is_some() {
            &self.policy.hooks.on_retry
        } else {
            &self.policy.hooks.on_error
        };
        if let Some(hook) = hook {
            hook(&self.context(error, wait));
        }
    }

    /// Start the next attempt and return its number, from 1.
    fn next_attempt(&mut self) -> u32 {
        self.attempt += 1;
        self.attempt
    }

    /// The base URL this attempt targets.
    fn base_url(&self) -> &'a str {
        self.endpoints[self.endpoint]
    }

    /// The URL of `path` on this attempt's endpoint.
    fn url(&mut self, path: &str) -> String {
        self.url = format!("{}{}", self.base_url(), path);
        self.url.clone()
    }

    /// Report a success response to the attempt hook and to `after_response`.
    fn after_success(&mut self, status: StatusCode) {
        self.status = Some(status.as_u16());
        self.report(Some(status), None, None);
        if let Some(hook) = &self.policy.hooks.after_response {
            hook(&self.context(None, None));
        }
    }

    /// The wait before retrying a failure status, or `None` to return its error.
    fn after_status(&mut self, status: StatusCode, headers: &HeaderMap) -> Option<Duration> {
        let wait = if self.retrying() && should_retry(status, headers) {
            self.wait(Some(headers))
        } else {
            None
        };
        self.status = Some(status.as_u16());
        self.report(Some(status), None, wait);
        let failure = wait.is_none().then(|| format!("HTTP {}", status.as_u16()));
        self.settle_failure(failure, wait);
        // A 5xx moves an idempotent call to the next endpoint; a 4xx retry, such as a 429, stays.
        if wait.is_some() && status.is_server_error() {
            self.advance();
        }
        wait
    }

    /// The wait before retrying a transport failure or timeout, or `None` to return it.
    fn after_error(&mut self, error: &reqwest::Error) -> Option<Duration> {
        let transient = error.is_timeout() || error.is_connect();
        let wait = if self.retrying() && transient {
            self.wait(None)
        } else {
            None
        };
        self.report(None, Some(error), wait);
        self.settle_failure(
            Some(redact_secrets(&error.to_string(), &self.secrets)),
            wait,
        );
        // No response arrived, so an idempotent call moves to the next endpoint.
        if wait.is_some() {
            self.advance();
        }
        wait
    }

    // A non-idempotent operation calls this once its headers are set: an
    // `Idempotency-Key` (a declared header parameter, `RequestOptions::headers` or a
    // default header) makes a retry safe on the same endpoint, never on a fallback.
    // A contract without a non-idempotent operation never calls it.
    #[allow(dead_code)]
    fn allow_if_keyed(&mut self, headers: &HeaderMap) {
        let keyed = headers.get("idempotency-key").is_some_and(|key| {
            key.as_bytes()
                .iter()
                .any(|byte| !byte.is_ascii_whitespace())
        });
        self.allowed = self.allowed || keyed;
    }

    fn retrying(&self) -> bool {
        self.allowed && self.attempt <= self.max_retries
    }

    // The last endpoint serves the remaining attempts.
    fn advance(&mut self) {
        self.endpoint = (self.endpoint + 1).min(self.endpoints.len() - 1);
    }

    /// The server's wait when it fits `max_retry_delay`, else no retry at all: the error
    /// is returned at once rather than retried early. Without one, jittered exponential
    /// backoff. A wait that would overrun `retry_budget` is not taken either.
    fn wait(&self, headers: Option<&HeaderMap>) -> Option<Duration> {
        let server = headers.and_then(server_retry_delay);
        if server.is_some_and(|requested| requested > self.policy.max_retry_delay) {
            return None;
        }
        let wait = server.unwrap_or_else(|| self.backoff());
        match self.policy.budget {
            Some(budget) if self.started.elapsed().saturating_add(wait) > budget => None,
            _ => Some(wait),
        }
    }

    /// 0.5 s doubling per attempt, at most 60 s and `max_retry_delay`, less up to half.
    fn backoff(&self) -> Duration {
        let ceiling = self.policy.max_retry_delay.min(Duration::from_secs(60));
        let base =
            Duration::from_millis(500_u64 << self.attempt.saturating_sub(1).min(16)).min(ceiling);
        let draw = self
            .policy
            .random
            .as_ref()
            .map_or_else(jitter, |random| random());
        let draw = if draw.is_finite() {
            draw.clamp(0.0, 1.0)
        } else {
            0.0
        };
        base.mul_f64(0.5 + draw * 0.5)
    }

    fn report(
        &self,
        status: Option<StatusCode>,
        error: Option<&reqwest::Error>,
        retry_delay: Option<Duration>,
    ) {
        if let Some(hook) = &self.policy.on_attempt {
            hook(&AttemptInfo {
                operation: self.operation.to_owned(),
                attempt: self.attempt,
                base_url: self.base_url().to_owned(),
                url: self.url.clone(),
                status,
                error: error.map(ToString::to_string),
                retry_delay,
            });
        }
    }

    /// Wait before the next attempt.
    async fn pause(&self, delay: Duration) {
        match &self.policy.sleep {
            Some(sleep) => sleep(delay),
            None => tokio::time::sleep(delay).await,
        }
    }
}

// The span of a call ends when its walk ends, whichever way the call returns.
impl Drop for RetryState<'_> {
    fn drop(&mut self) {
        if let Some(span) = self.span.take() {
            let resends = SpanValue::Int(i64::from(self.attempt.saturating_sub(1)));
            let mut attributes = vec![("http.request.resend_count", resends)];
            if let Some(status) = self.status {
                attributes.push((
                    "http.response.status_code",
                    SpanValue::Int(i64::from(status)),
                ));
            }
            span.end(&attributes);
        }
    }
}

const REDACTED: &str = "[redacted]";

/// Every configured credential value, redacted from hook contexts and spans.
fn secret_values(auth: &Authentication) -> Vec<String> {
    let mut values: Vec<String> = auth
        .api_keys
        .values()
        .chain(auth.bearer_tokens.values())
        .cloned()
        .collect();
    values.extend(auth.bearer_token.iter().cloned());
    values.extend(
        auth.default_basic
            .iter()
            .map(|basic| basic.password.clone()),
    );
    values.extend(auth.basic.values().map(|basic| basic.password.clone()));
    values
}

fn redact_secrets(text: &str, secrets: &[String]) -> String {
    let mut text = text.to_owned();
    for secret in secrets.iter().filter(|secret| secret.len() >= 4) {
        text = text.replace(secret.as_str(), REDACTED);
    }
    text
}

/// A copy of the request headers with every credential header redacted.
fn redacted_headers(headers: &HeaderMap, secrets: &[String]) -> Vec<(String, String)> {
    let hidden = credential_names("header");
    let mut observed = Vec::new();
    for (name, value) in headers {
        let shown = if hidden.iter().any(|item| *item == name.as_str()) {
            REDACTED.to_owned()
        } else {
            redact_secrets(value.to_str().unwrap_or("<binary>"), secrets)
        };
        observed.push((name.as_str().to_owned(), shown));
    }
    observed
}

/// The request URL, query included, with every API-key query value redacted.
fn redacted_url(url: &str, query: &[(String, String)], secrets: &[String]) -> String {
    let hidden = credential_names("query");
    let mut rendered = url.to_owned();
    for (index, (name, value)) in query.iter().enumerate() {
        rendered.push(if index == 0 && !url.contains('?') {
            '?'
        } else {
            '&'
        });
        rendered.push_str(&urlencoding::encode(name));
        rendered.push('=');
        if hidden.iter().any(|item| item.eq_ignore_ascii_case(name)) {
            rendered.push_str(REDACTED);
        } else {
            rendered.push_str(&urlencoding::encode(value));
        }
    }
    redact_secrets(&rendered, secrets)
}

